#ifndef SCENARIODATA_SCENARIODATA_HPP_
#define SCENARIODATA_SCENARIODATA_HPP_

#include <stdint.h>

/************************************
 * MACROS AND DEFINES
 ************************************/
constexpr float SCENARIO_DT = 0.1f;		// s between rows before apogee
constexpr float SCENARIO_DESCENT_DT = 1.0f;	// s between rows after apogee
constexpr uint8_t SCENARIO_COUNT = 9;

/************************************
 * TYPEDEFS
 ************************************/
/**
 * @brief One row of a simulated flight, pad relative, up positive
 */
struct ScenarioPoint
{
	float time;			// s since ignition
	float altitude;		// m above the pad
	float velocity;		// m/s
	float acceleration;	// m/s^2, kinematic (gravity included in the motion)
};

/**
 * @brief One simulated flight (MAPLEAF case), split at apogee
 */
struct ScenarioCase
{
	const char* name;
	const ScenarioPoint* before;	// Ignition -> apogee
	uint16_t beforeCount;
	const ScenarioPoint* after;		// Apogee -> landing
	uint16_t afterCount;
	bool afterSynthetic;			// true: descent built from the legacy sim, not this case
	float apogeeAltitude;			// m above the pad
	float apogeeTime;				// s since ignition
};

/************************************
 * VARIABLES
 ************************************/
extern const ScenarioCase SCENARIOS[SCENARIO_COUNT];

#endif /* SCENARIODATA_SCENARIODATA_HPP_ */
